List<int> unique(List<int> list) {
  // If the input list is empty, return an empty list.
  if (list.isEmpty) {
    return [];
  }

  // Create a new list to hold the unique elements and add the first element.
  final List<int> uniqueElements = [list[0]];

  // Keep track of the previous element to compare against.
  int prevElement = list[0];

  // Iterate through the rest of the list starting from index 1.
  for (int i = 1; i < list.length; i++) {
    // Check if current element is different than the previous one.
    if (prevElement != list[i]) {
      // Add it to the list of unique elements.
      uniqueElements.add(list[i]);
      // Update the previous element to be the current one.
      prevElement = list[i];
    }
  }

  return uniqueElements;
}

