class MyCircularQueue {
  late List<String> queue;
  int frontIndex = 0;
  int rearIndex = 0;
  int capacity;

  MyCircularQueue(int k) : capacity = k {
    queue = List.filled(k, '');
  }

  bool enQueue(String element) {
    if (isFull()) return false;
    queue[rearIndex++] = element;
    rearIndex %= capacity;
    return true;
  }

  bool deQueue() {
    if (isEmpty()) return false;
    frontIndex++;
    frontIndex %= capacity;
    return true;
  }

  String? peek() {
    if (isEmpty()) return null;
    return queue[frontIndex];
  }

  bool isEmpty() => frontIndex == rearIndex;

  bool isFull() => (rearIndex + 1) % capacity == frontIndex;
}
