import 'dart:collection';
import 'dart:io';

class Solution {
  static bool sameChars(String s0, String s1) {
    if (s0.length != s1.length) return false;

    int len = s0.length;
    List<int> charsS0 = List<int>.filled(len, 0);
    List<int> charsS1 = List<int>.filled(len, 0);

    // Convert strings to ASCII values and store in lists
    for (int i = 0; i < len; ++i) {
      charsS0[i] = s0.codeUnitAt(i);
      charsS1[i] = s1.codeUnitAt(i);
    }

    // Use a set to check for duplicate characters
    Set<int> uniqueCharsS0 = HashSet<int>();
    Set<int> uniqueCharsS1 = HashSet<int>();

    for (int ch in charsS0) {
      uniqueCharsS0.add(ch);
    }

    for (int ch in charsS1) {
      uniqueCharsS1.add(ch);
    }

    // Check if both sets have the same number of unique characters
    if (uniqueCharsS0.length != uniqueCharsS1.length) {
      return false;
    }

    // Compare each character count between the two sets
    for (int ch in uniqueCharsS0) {
      if (!uniqueCharsS1.contains(ch)) {
        return false;
      }
    }

    return true;
  }
}

