List<int> sortArray(List<int> array) {
  if (array.isEmpty || array.length == 1) return array;

  int n = array.length;
  for (int i = 0; i < n - 1; i++) {
    bool swapped = false;

    // Last i elements are already in place
    for (int j = 0; j < n - i - 1; j++) {
      if (array[j] > array[j + 1]) {
        // Swap the elements
        int temp = array[j];
        array[j] = array[j + 1];
        array[j + 1] = temp;
        swapped = true;
      }
    }

    // If no two adjacent elements were swapped, the list is sorted
    if (!swapped) break;
  }

  return array;
}

