// This function counts the number of sentences that start and end with the same word.
// It splits the input string into sentences, checks each one to see if it starts and ends with the same word,
// and increments a counter accordingly.

// Example:
// Input: "Hello world. Hello there. How are you?"
// Output: 1 (Only the first sentence "Hello world" has the same starting and ending word)

int isBored(String s) {
  // Split the input string into individual sentences using '.' as the delimiter
  final List<String> sentences = s.split('.').where((element) => element.isNotEmpty).toList();

  // Initialize a counter to keep track of matching sentences
  int count = 0;

  // Iterate through each sentence
  for (var sentence in sentences) {
    // Check if the sentence is not empty after trimming whitespace
    if (sentence.trim().isNotEmpty && !sentence.endsWith('?')) {
      // Split the sentence into individual words
      final List<String> words = sentence.split(' ').where((word) => word.isNotEmpty).toList();

      // If the sentence has at least two words
      if (words.length >= 2) {
        // Extract the first and last words, trimmed of any leading/trailing spaces
        final String firstWord = words[0].trim();
        final String lastWord = words.last.trim();

        // If the first and last words are the same, increment the counter
        if (firstWord == lastWord) {
          count++;
        }
      }
    }
  }

  // Return the total count of such sentences
  return count;
}

