    dp[i][0] = min(dp[i - 1][0], grid[i][0]);
  }
  for (var j = 1; j < cols; j++) {
    dp[0][j] = min(dp[0][j-1], grid[0][j]);
  }

  // Fill the rest of the cells using dynamic programming approach
  for (var i = 1; i < rows; i++) {
    for (var j = 1; j < cols; j++) {
      dp[i][j] = min(min(dp[i - 1][j], dp[i][j - 1]), grid[i][j]) + dp[i - 1][j - 1];
    }
  }

  // The answer is stored at the bottom-right corner of the DP table
  return dp[rows - 1][cols - 1];
}

