int maxFill(List<List<int>> grid, int capacity) {
  final rows = grid.length;
  if (rows == 0) return 0;
  final cols = grid[0].length;

  // Directions for up, down, left, right
  final directions = <List<int>>[
    [-1, 0],
    [1, 0],
    [0, -1],
    [0, 1]
  ];

  // For each cell in the grid, we'll track how much water it can hold when acting as a basin
  final heightMap = List.filled(rows * cols, 0);

  void updateHeights(int row, int col, int currentHeight, int index) {
    if (row < 0 || row >= rows || col < 0 || col >= cols) return; // out of bounds

    final isBoundary = row == 0 || row == rows-1 || col == 0 || col == cols-1;

    final currentCellHeight = grid[row][col];

    // If this cell is on boundary or has lower height than our starting point,
    // then its contribution to the total fill is min(currentHeight, currentCellHeight)
    // and we need to add that to the result.
    // Otherwise, we have an internal cell which might be able to collect more water based on surrounding cells.
    final contribute = min(currentHeight, currentCellHeight);
    heightMap[index] += contribute;

    // We continue exploring all four directions from the current cell
    for (final dir in directions) {
      final newRow = row + dir[0];
      final newCol = col + dir[1];

      // Recursively check adjacent cells with updated parameters
      updateHeights(newRow, newCol, contribute, index + 1);
    }
  }

  // Start with top-left corner, assuming it's part of the path where water can flow
  updateHeights(0, 0, grid[0][0], 0);

  // The maximum amount of fill possible is limited by the given capacity
  final maxPossible = heightMap.reduce((a, b) => a + b).min(capacity);
  return maxPossible;
}

