int maxFill(List<List<int>> grid, int capacity) {
  final rows = grid.length;
  if (rows == 0) return 0;

  final cols = grid[0].length;
  final totalCapacity = rows * cols * capacity;

  // Check for invalid input
  if (totalCapacity < 1 || capacity <= 0 || rows <= 0 || cols <= 0) {
    return -1; // Invalid input case
  }

  final visited = List<bool>.filled(rows * cols, false);
  final directions = [
    [0, 1],   // Right
    [1, 0],   // Down
    [-1, 0],  // Up
    [0, -1]   // Left
  ];

  var result = 0;
  final queue = Queue();

  for (var i = 0; i < rows; ++i) {
    for (var j = 0; j < cols; ++j) {
      if (!visited[i * cols + j]) {
        final area = bfs(grid, visited, i, j, directions, rows, cols, capacity);
        result += area;
      }
    }
  }

  return result;
}

// Helper function to perform BFS and calculate the maximum fillable area in a connected region
int bfs(
  List<List<int>> grid,
  List<bool> visited,
  int row,
  int col,
  List<List<int>> directions,
  int rows,
  int cols,
  int capacity,
) {
  final queue = Queue();
  final size = rows * cols;
  final isWithinBounds = (r, c) => r >= 0 && r < rows && c >= 0 && c < cols;
  final initialCell = grid[row][col];

  if (initialCell == 0) return 0; // Skip empty cells

  queue.add([row, col]);
  visited[row * cols + col] = true;
  int area = 0;

  while (queue.isNotEmpty) {
    final current = queue.removeFirst();
    final currRow = current[0];
    final currCol = current[1];

    area++;

    for (final dir in directions) {
      final newRow = currRow + dir[0];
      final newCol = currCol + dir[1];

      if (
        isWithinBounds(newRow, newCol) &&
        !visited[newRow * cols + newCol] &&
        grid[newRow][newCol] == initialCell
      ) {
        visited[newRow * cols + newCol] = true;
        queue.add([newRow, newCol]);
      }
    }
  }

  return min(area, capacity); // Ensure we don't exceed the given capacity
}

