int maxFill(List<List<int>> grid, int capacity) {
  if (grid.isEmpty || grid[0].isEmpty) return 0;

  final rows = grid.length;
  final cols = grid[0].length;

  // Create a matrix to keep track of the maximum number of books that can be filled
  // at each cell with the given capacity.
  var dp = List.generate(rows + 1, (_) => List.filled(cols + 1, 0));

  for (var i = rows - 1; i >= 0; i--) {
    for (var j = cols - 1; j >= 0; j--) {
      // The current cell's value is either:
      // 1. The same as not taking this book shelf (dp[i+1][j])
      // 2. Or, if we take it, then the total will be the minimum between the remaining space in the truck and the height of the shelf,
      //   plus whatever was previously possible on the next row or column.

      // Calculate the maximum fill by considering both options
      var option1 = dp[i + 1][j];
      var option2 = min(capacity, grid[i][j]) + dp[i + 1][j + 1];

      dp[i][j] = max(option1, option2);
    }
  }

  return dp[0][0];
}

