int maxFill(List<List<int>> grid, int capacity) {
  final rows = grid.length;
  if (rows == 0 || capacity < 1) return 0;

  final cols = grid[0].length;
  final visited = List.generate(rows, (_) => List.filled(cols, false));

  // Directions: right, down, left, up
  const directions = [Vector(0, 1), Vector(1, 0), Vector(0, -1), Vector(-1, 0)];

  bool isWithinBound(int row, int col) =>
      row >= 0 && row < rows && col >= 0 && col < cols;

  void dfs(int row, int col, int currentCapacity) {
    if (!isWithinBound(row, col)) return; 
    if (visited[row][col]) return;

    if (grid[row][col] > capacity) return;

    visited[row][col] = true;

    for (final direction in directions) {
      final nextRow = row + direction.row;
      final nextCol = col + direction.col;

      if (nextRow <= row && nextCol <= col) continue; // move only to the right and down

      dfs(nextRow, nextCol, currentCapacity);
    }

    // Check if we can fill this cell with the available capacity
    if (currentCapacity > 0 && grid[row][col] != 0) {
      if (grid[row][col] <= currentCapacity) {
        final newCapacity = currentCapacity - grid[row][col];

        // Try all possible directions from here
        for (final direction in directions) {
          final nextRow = row + direction.row;
          final nextCol = col + direction.col;

          if (isWithinBound(nextRow, nextCol) && !visited[nextRow][nextCol]) {
            dfs(nextRow, nextCol, newCapacity);
          }
        }
      }
    } else if (currentCapacity == 0) {
      return; // No more capacity to use
    } else {
      // If no more cells to go, but not filled completely
      if (currentCapacity > 0) {
        // Can't do anything, backtrack
        visited[row][col] = false;
        return;
      }
    }
  }

  var result = 0;

  for (var i = 0; i < rows; ++i) {
    for (var j = 0; j < cols; ++j) {
      if (grid[i][j] == 0) continue; // skip empty cells
      final initialCapacity = min(capacity, grid[i][j]);
      dfs(i, j, initialCapacity); // start DFS from this cell
      result += initialCapacity;
    }
  }

  return result;
}

