int maxFill(List<List<int>> grid, int capacity) {
  final rows = grid.length;
  if (rows == 0 || grid[0].length == 0) return 0;

  final cols = grid[0].length;

  // Create a prefix sum matrix
  var prefixSums = List.generate(rows + 1, (_) => List.filled(cols + 1, 0));

  for (var i = 1; i <= rows; ++i) {
    for (var j = 1; j <= cols; ++j) {
      prefixSums[i][j] = grid[i-1][j-1] + 
                         prefixSums[i-1][j] +
                         prefixSums[i][j-1] -
                         prefixSums[i-1][j-1];
    }
  }

  // Binary search on the maximum area
  var left = 1;
  var right = min(256, min(rows, cols)); // Maximum possible square size is 2^8
  var bestArea = 0;

  while (left <= right) {
    var mid = (left + right) ~/ 2;

    // Check if we can fit a square of side length `mid`
    bool canPlace(int k) {
      for (var x1 = 1; x1 <= rows - k + 1; ++x1) {
        for (var y1 = 1; y1 <= cols - k + 1; ++y1) {
          var x2 = x1 + k - 1;
          var y2 = y1 + k - 1;

          // Calculate the total water in this submatrix using prefix sums
          var total = prefixSums[x2][y2] - prefixSums[x1-1][y2] - prefixSums[x2][y1-1] + prefixSums[x1-1][y1-1];

          // If total doesn't exceed capacity and area >= current best, update best
          if (total <= capacity && (k*k > bestArea)) {
            bestArea = k * k;
            break; // Early exit since we're checking from top-left to bottom-right
          }
        }
      }

      return false; // No need to check further once we found one valid position
    }

    if (canPlace(mid)) {
      bestArea = mid * mid;
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }

  return bestArea;
}

