// It sorts an array in ascending order by repeatedly swapping adjacent elements
// if they are in the wrong order.

import 'dart:math';

List<int> sortArray(List<int> arr) {
  // Handle empty or single-element arrays immediately
  if (arr.isEmpty || arr.length == 1) return List.from(arr);

  int n = arr.length;

  // Perform bubble sort with optimization to stop early if no swaps occur
  for (int i = 0; i < n - 1; i++) {
    bool swapped = false;

    // Last i elements are already in place
    for (int j = 0; j < n - 1 - i; j++) {
      // Swap if current element is greater than next
      if (arr[j] > arr[j + 1]) {
        int temp = arr[j];
        arr[j] = arr[j + 1];
        arr[j + 1] = temp;
        swapped = true;
      }
    }

    // If no swaps occurred, the list is sorted
    if (!swapped) break;
  }

  return arr;
}
