List<int> maximum(List<int> arr, int k) {
  if (k == 0 || arr.isEmpty) return [];

  final n = arr.length;
  final result = List<int>.filled(n - k + 1, 0);
  final deque = Deque<int>();

  for (int i = 0; i < n; i++) {
