List<String> getFactors(String numberStr) {
  int number = int.parse(numberStr);
  List<String> factors = [];

  if (number < 0) {
    factors.add('-');
    number *= -1;
  }

  if (number == 1) {
    return ['1'];
  } else if (number == 0) {
    return ['0'];
  }

  bool isNegative = false;
  if (number < 0) {
    isNegative = true;
    number *= -1;
  }

  while (number > 1) {
    int divisor = findSmallestPrimeFactor(number);
    if (divisor == null) break; // Should not happen as we check all primes

    factors.add(divisor.toString());

    number /= divisor;
  }

  if (!isNegative) {
    if (factors.isEmpty) {
      factors.add('1'); // Handle case when input was zero or something like that
    }
  } else {
    factors.add('-');
    if (factors.length % 2 != 0) {
      factors.removeLast();
      factors.add('1');
    }
  }

  return factors;
}

int findSmallestPrimeFactor(int num) {
  if (num % 2 == 0) return 2;

  for (int i = 3; i <= sqrt(num); i += 2) {
    if (num % i == 0) return i;
  }

  return num; // The number itself is prime
}

