void generatePatterns(String remainingPattern, String currentPattern, List<String> result, List<String> patterns) {
  if (remainingPattern.isEmpty) {
    result.add(currentPattern);
    return;
  }

  for (int i = 0; i < remainingPattern.length; ++i) {
    String nextChar = remainingPattern[i];

    // Skip duplicate characters to avoid generating duplicates
    if (i > 0 && remainingPattern[i] == remainingPattern[i - 1]) continue;

    // Recursively build new patterns by adding next character at different positions
    for (int j = 0; j <= currentPattern.length + 1; ++j) {
      String updatedCurrent = currentPattern.substring(0, j) + nextChar + currentPattern.substring(j);
      generatePatterns(
        remainingPattern.substring(i + 1),
        updatedCurrent,
        result,
        patterns
      );
    }
  }
