import 'dart:core';

bool cycpatternCheck(String a, String b) {
  if (a.isEmpty || b.isEmpty) return false;

  // Check if the pattern is valid and extract it.
  final pattern = _extractPattern(b);
  if (pattern == null) return false;

  int index = 0;
  for (int i = 0; i < a.length; ++i) {
    if (index >= pattern.length) break;

    if (a[i] != pattern[index]) {
      if (i + 1 > a.length - 2 && !pattern.contains(a[i])) {
        return false;
      }
      index = 0;
    } else {
      ++index;
    }
  }

  return true;
}

String? _extractPattern(String s) {
  var current = '';
  var prev = '';
  bool firstChar = true;

  for (var c in s.split('')) {
    if (c == '{') {
      if (!firstChar) return null;
      firstChar = false;
      continue;
    } else if (c == '}') {
      if (current.isNotEmpty) {
        prev += current;
        current = '';
      }
      break;
    } else if (prev.isEmpty) {
      prev += c;
    } else {
      current += c;
    }
  }

  if (current.isNotEmpty) return null;

  if (prev.isEmpty) return null;

  while (prev.endsWith(prev[0])) {
    prev = prev.substring(0, prev.length - 1);
  }

  return prev;
}
